export const axisTooltipGetter = series => {
  return Object.values(series).map(s => s.layout === 'horizontal' ? {
    direction: 'radius',
    axisId: 'radiusAxisId' in s ? s.radiusAxisId : undefined
  } : {
    direction: 'rotation',
    axisId: 'rotationAxisId' in s ? s.rotationAxisId : undefined
  });
};